import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Item","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/item.md","filePath":"03-developer/models/item.md"}`),a={name:`03-developer/models/item.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="item" tabindex="-1">Item <a class="header-anchor" href="#item" aria-label="Permalink to “Item”">​</a></h1><p>The <code>Item</code> model stores a menu item, such as a link to a post, product, group, or category, or a direct link to a custom path.</p><p>Each item belongs to a menu and can have child items. The item type is specified by <code>kind</code>, and its destination is determined by the <code>menuable</code> relationship or the value of <code>meta</code>, depending on the type.</p><h2 id="items-table-structure" tabindex="-1"><code>items</code> table structure <a class="header-anchor" href="#items-table-structure" aria-label="Permalink to “items table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>Item ID</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>Display title of the item; the same as its Label</td></tr><tr><td><code>menuable_id</code></td><td>BIGINT UNSIGNED NULL</td><td>ID of the destination entity in the polymorphic relationship</td></tr><tr><td><code>menuable_type</code></td><td>VARCHAR(255) NULL</td><td>Class of the destination entity in the polymorphic relationship</td></tr><tr><td><code>kind</code></td><td>VARCHAR(255) NULL</td><td>Item type, such as <code>module</code> or <code>direct</code></td></tr><tr><td><code>meta</code></td><td>TEXT NULL</td><td>Direct link address when <code>kind</code> is <code>direct</code></td></tr><tr><td><code>parent</code></td><td>INT UNSIGNED NULL</td><td>Parent item ID, used to create nested menus</td></tr><tr><td><code>sort</code></td><td>INT UNSIGNED</td><td>Item display order; defaults to <code>0</code></td></tr><tr><td><code>icon</code></td><td>VARCHAR(255) NULL</td><td>Remix Icon name</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>ID of the user associated with the item</td></tr><tr><td><code>menu_id</code></td><td>BIGINT UNSIGNED</td><td>ID of the menu the item belongs to</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP NULL</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP NULL</td><td>Last update time</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="title-translation" tabindex="-1">Title translation <a class="header-anchor" href="#title-translation" aria-label="Permalink to “Title translation”">​</a></h3><div class="language-php"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $translatable </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;title&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>The <code>title</code> field is translatable and can display the item title in the current language.</p><h3 id="item-type-and-destination" tabindex="-1">Item type and destination <a class="header-anchor" href="#item-type-and-destination" aria-label="Permalink to “Item type and destination”">​</a></h3><p>The <code>kind</code> field specifies how the item link is constructed:</p><ul><li><strong><code>module</code></strong>: The item is connected to an entity through the polymorphic <code>menuable</code> relationship, such as a post, product, group, or category.</li><li><strong><code>direct</code></strong>: The direct link is read from the <code>meta</code> field and does not require a destination entity.</li></ul><p>In this design, <code>menuable</code> represents a model-based destination, while <code>meta</code> represents a URL-based destination. These are two different ways to specify an item&#39;s destination.</p><h2 id="methods-and-relationships" tabindex="-1">Methods and relationships <a class="header-anchor" href="#methods-and-relationships" aria-label="Permalink to “Methods and relationships”">​</a></h2><h3 id="menu" tabindex="-1"><code>menu()</code> <a class="header-anchor" href="#menu" aria-label="Permalink to “menu()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./menu.html">Menu</a> model.</p><p>This relationship can be used to retrieve the menu the item belongs to. The foreign key is <code>menu_id</code>, and the referenced key is <code>id</code>.</p><h3 id="parent" tabindex="-1"><code>parent()</code> <a class="header-anchor" href="#parent" aria-label="Permalink to “parent()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <code>Item</code> model itself and finds the parent item through the <code>parent</code> field.</p><p>This relationship is used to create menu hierarchies.</p><h3 id="children" tabindex="-1"><code>children()</code> <a class="header-anchor" href="#children" aria-label="Permalink to “children()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <code>Item</code> model itself and returns all items whose <code>parent</code> value matches the current item&#39;s ID.</p><h3 id="dest" tabindex="-1"><code>dest()</code> <a class="header-anchor" href="#dest" aria-label="Permalink to “dest()”">​</a></h3><p>Defines a polymorphic <code>morphTo</code> relationship named <code>menuable</code> and determines the item&#39;s destination using the following two fields:</p><ul><li><code>menuable_type</code>: Class of the destination model</li><li><code>menuable_id</code>: ID of the destination record</li></ul><p>The destination type can be one of the models supported in the <code>$mrohps</code> list of the <code>Menu</code> model.</p><h3 id="weburl" tabindex="-1"><code>webUrl()</code> <a class="header-anchor" href="#weburl" aria-label="Permalink to “webUrl()”">​</a></h3><p>Generates the final menu item URL based on the value of <code>kind</code>.</p><p><strong>For <code>direct</code> items:</strong></p><ul><li>The URL is read from the <code>meta</code> field.</li><li>If the multilingual feature <code>app.xlang.active</code> is enabled and the current language differs from the default language, the method attempts to add the current language to the URL.</li><li>If the URL starts with <code>/</code>, the language prefix is added to the beginning of the path.</li><li>Otherwise, the home page URL is obtained through <code>route(&#39;client.welcome&#39;)</code> and replaced with its language-specific version.</li><li>In the default language, or when the multilingual feature is disabled, the <code>meta</code> value is returned unchanged.</li></ul><p><strong>For items other than <code>direct</code>:</strong></p><p>The <code>webUrl()</code> method retrieves the destination entity through <code>dest()</code> and calls that entity&#39;s <code>webUrl()</code> method.</p><p>Therefore, for module items, the destination model must provide a <code>webUrl()</code> method.</p><h2 id="database-and-implementation-notes" tabindex="-1">Database and implementation notes <a class="header-anchor" href="#database-and-implementation-notes" aria-label="Permalink to “Database and implementation notes”">​</a></h2><ul><li>The <code>menu_id</code> and <code>user_id</code> fields have foreign keys, and <code>ON DELETE RESTRICT</code> prevents referenced records from being deleted when dependent items exist.</li><li>The <code>parent</code> field has an index, but the provided SQL does not define a foreign key from it to <code>items.id</code>. As a result, this database definition alone does not guarantee parent-child relationship integrity.</li><li>The type of <code>parent</code> is <code>INT UNSIGNED</code>, while <code>id</code> is <code>BIGINT UNSIGNED</code>. This type mismatch is worth reviewing.</li><li>In the <code>webUrl()</code> method, accessing <code>$this-&gt;meta[0]</code> assumes that <code>meta</code> contains a usable value. Since <code>meta</code> is nullable in the database, the behavior of <code>direct</code> items without a URL should also be reviewed.</li><li>For items other than <code>direct</code>, the method assumes that the destination is valid. If <code>dest()</code> returns <code>null</code>, calling <code>webUrl()</code> on it will cause an error.</li></ul>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};